 public function can_manage_presets(){return current_user_can('edit_nirmaan_design');}
 private function style_presets(){ $items=get_option('nirmaan_builder_style_presets',array());return is_array($items)?$items:array(); }
 private function sanitize_preset_payload($p){
  if(!is_array($p))return new \WP_Error('invalid_preset',__('Invalid style preset.','nirmaan-builder'),array('status'=>400));
  $name=sanitize_text_field($p['name']??'');
  if(''===$name||strlen($name)>80)return new \WP_Error('invalid_preset_name',__('Preset name is required and must be 80 characters or fewer.','nirmaan-builder'),array('status'=>400));
  $styles=is_array($p['styles']??null)?$p['styles']:array();
  $clean=array();
  foreach(array('desktop','tablet','mobile') as $device){$clean[$device]=$this->sanitize_style(is_array($styles[$device]??null)?$styles[$device]:array());}
  if(!array_filter($clean))return new \WP_Error('empty_preset',__('Add at least one supported style before saving.','nirmaan-builder'),array('status'=>400));
  $category=sanitize_key($p['category']??'element');
  if(!in_array($category,array('element','typography','color','button','container'),true))$category='element';
  return array('name'=>$name,'category'=>$category,'styles'=>$clean,'version'=>1,'updated_at'=>current_time('mysql',true));
 }
 public function list_style_presets(){ $items=$this->style_presets();return rest_ensure_response(array_values($items)); }
 public function create_style_preset($r){
  $preset=$this->sanitize_preset_payload($r->get_json_params());if(is_wp_error($preset))return $preset;
  $items=$this->style_presets();if(count($items)>=200)return new \WP_Error('preset_limit',__('Maximum of 200 style presets reached.','nirmaan-builder'),array('status'=>400));
  $id='preset-'.str_replace('-','',wp_generate_uuid4());$preset['id']=$id;$items[$id]=$preset;update_option('nirmaan_builder_style_presets',$items,false);
  return rest_ensure_response(array('created'=>true,'preset'=>$preset));
 }
 public function update_style_preset($r){
  $id=sanitize_key($r['id']);$items=$this->style_presets();if(!isset($items[$id]))return new \WP_Error('preset_not_found',__('Style preset not found.','nirmaan-builder'),array('status'=>404));
  $preset=$this->sanitize_preset_payload($r->get_json_params());if(is_wp_error($preset))return $preset;
  $preset['id']=$id;$items[$id]=$preset;update_option('nirmaan_builder_style_presets',$items,false);
  return rest_ensure_response(array('saved'=>true,'preset'=>$preset));
 }
 private function snapshot_preset_nodes($nodes,$id,$styles){
  if(!is_array($nodes))return array(false,$nodes);$changed=false;
  foreach($nodes as &$node){if(!is_array($node))continue;$settings=is_array($node['settings']??null)?$node['settings']:array();
   if(($settings['style_preset_id']??'')===$id){$fallback=is_array($settings['preset_fallback']??null)?$settings['preset_fallback']:array();foreach(array('desktop','tablet','mobile') as $device){$settings[$device]=array_merge($fallback[$device]??array(),$styles[$device]??array(),is_array($settings[$device]??null)?$settings[$device]:array());}unset($settings['style_preset_id'],$settings['preset_fallback']);$node['settings']=$settings;$changed=true;}
   if(isset($node['children'])&&is_array($node['children'])){list($child_changed,$node['children'])=$this->snapshot_preset_nodes($node['children'],$id,$styles);$changed=$changed||$child_changed;}
  }unset($node);return array($changed,$nodes);
 }
 private function preserve_deleted_preset_references($id,$styles){
  $post_types=array_values(get_post_types(array(),'names'));$page=1;
  do{
   $post_ids=get_posts(array('post_type'=>$post_types,'post_status'=>array_keys(get_post_stati()),'numberposts'=>100,'paged'=>$page,'fields'=>'ids','meta_query'=>array('relation'=>'OR',array('key'=>'_nirmaan_builder_document','compare'=>'EXISTS'),array('key'=>'_nirmaan_library_document','compare'=>'EXISTS'),array('key'=>'_nirmaan_template_parts','compare'=>'EXISTS'),array('key'=>'_nirmaan_builder_autosaves','compare'=>'EXISTS'),array('key'=>'_nirmaan_builder_revisions','compare'=>'EXISTS'))));
   foreach($post_ids as $post_id){
    foreach(array('_nirmaan_builder_document','_nirmaan_library_document') as $key){$doc=get_post_meta($post_id,$key,true);if(is_array($doc)&&isset($doc['nodes'])){list($changed,$doc['nodes'])=$this->snapshot_preset_nodes($doc['nodes'],$id,$styles);if($changed)update_post_meta($post_id,$key,$doc);}}
    $parts=get_post_meta($post_id,'_nirmaan_template_parts',true);if(is_array($parts)){$changed=false;foreach($parts as &$part){if(is_array($part)&&isset($part['nodes'])){list($part_changed,$part['nodes'])=$this->snapshot_preset_nodes($part['nodes'],$id,$styles);$changed=$changed||$part_changed;}}unset($part);if($changed)update_post_meta($post_id,'_nirmaan_template_parts',$parts);}
    $drafts=get_post_meta($post_id,'_nirmaan_builder_autosaves',true);if(is_array($drafts)){$changed=false;foreach($drafts as &$draft){if(is_array($draft['document']['nodes']??null)){list($draft_changed,$draft['document']['nodes'])=$this->snapshot_preset_nodes($draft['document']['nodes'],$id,$styles);$changed=$changed||$draft_changed;}}unset($draft);if($changed)update_post_meta($post_id,'_nirmaan_builder_autosaves',$drafts);}
    $revisions=get_post_meta($post_id,'_nirmaan_builder_revisions',true);if(is_array($revisions)){$changed=false;foreach($revisions as &$revision){if(is_array($revision['document']['nodes']??null)){list($revision_changed,$revision['document']['nodes'])=$this->snapshot_preset_nodes($revision['document']['nodes'],$id,$styles);$changed=$changed||$revision_changed;}}unset($revision);if($changed)update_post_meta($post_id,'_nirmaan_builder_revisions',$revisions);}
   }
   $page++;
  }while(count($post_ids)===100);
 }
 public function delete_style_preset($r){
  $id=sanitize_key($r['id']);$items=$this->style_presets();if(!isset($items[$id]))return new \WP_Error('preset_not_found',__('Style preset not found.','nirmaan-builder'),array('status'=>404));
  $this->preserve_deleted_preset_references($id,$items[$id]['styles']??array());
  unset($items[$id]);update_option('nirmaan_builder_style_presets',$items,false);return rest_ensure_response(array('deleted'=>true,'references_preserved'=>true));
 }
 public function status(){return rest_ensure_response(array('name'=>'Nirmaan Builder','version'=>NIRMAAN_BUILDER_VERSION,'status'=>'builder-expanded'));}
 public function can_manage_settings(){return current_user_can('manage_nirmaan_settings');}
 public function get_settings(){return rest_ensure_response(Settings::get());}
 public function save_settings($request){
  $params=$request->get_json_params();
  $settings=Settings::sanitize($params);
  update_option(Settings::OPTION,$settings,false);
  return rest_ensure_response(array('saved'=>true,'settings'=>$settings));
 }
 public function get_custom_fields($r){$id=absint($r['id']);$fields=get_post_meta($id,'_nirmaan_builder_custom_fields',true);return rest_ensure_response(array('fields'=>is_array($fields)?$fields:array()));}
 public function save_custom_fields($r){
  $id=absint($r['id']);$input=$r->get_json_params();$fields=is_array($input['fields']??null)?$input['fields']:array();$clean=array();
  foreach(array_slice($fields,0,30,true) as $key=>$value){$key=sanitize_key((string)$key);if(''===$key||strlen($key)>64||0===strpos($key,'_'))continue;if(is_array($value)||is_object($value))continue;$clean[$key]=sanitize_textarea_field((string)$value);if(strlen($clean[$key])>5000)$clean[$key]=substr($clean[$key],0,5000);}
  update_post_meta($id,'_nirmaan_builder_custom_fields',$clean);return rest_ensure_response(array('saved'=>true,'fields'=>$clean));
 }
 private function nodes_require_advanced_modules($nodes){if(!is_array($nodes))return false;$advanced=array('form','query_loop','product_title','product_price','product_image','product_gallery','product_add_to_cart','product_description','product_rating','product_meta','product_sale_flash','product_tabs','product_sku','product_stock','product_categories','product_breadcrumbs','related_products','shop_products','cart','checkout','mini_cart','product_archive');foreach($nodes as $node){if(!is_array($node))continue;if(in_array($node['type']??'', $advanced, true))return true;if($this->nodes_require_advanced_modules($node['children']??array()))return true;}return false;}
  private function post_requires_advanced_modules($id){foreach(array('_nirmaan_builder_document','_nirmaan_library_document') as $key){$doc=get_post_meta($id,$key,true);if(is_array($doc)&&$this->nodes_require_advanced_modules($doc['nodes']??array()))return true;}$parts=get_post_meta($id,'_nirmaan_template_parts',true);if(is_array($parts)){foreach($parts as $part){if(is_array($part)&&$this->nodes_require_advanced_modules($part['nodes']??array()))return true;}}return false;}
  public function can_edit_content($r){$id=absint($r['id']);if(!$id||!current_user_can('use_nirmaan_builder')||!current_user_can('use_nirmaan_modules')||!current_user_can('edit_nirmaan_content')||!current_user_can('edit_post',$id))return false;return current_user_can('use_nirmaan_advanced_modules')||!$this->post_requires_advanced_modules($id);}
 public function can_access_document($r){$type=sanitize_key($r['type']??'');if('content'===$type)return $this->can_edit_content($r);if('template'===$type)return $this->can_manage_templates($r);if('library'===$type)return $this->can_manage_library($r);return false;}
 public function can_manage_templates($r=null){if(!current_user_can('manage_nirmaan_templates')||!current_user_can('use_nirmaan_modules'))return false;if($r&&isset($r['id'])){$p=get_post(absint($r['id']));return $p&&'nirmaan_template'===$p->post_type&&(current_user_can('use_nirmaan_advanced_modules')||!$this->post_requires_advanced_modules($p->ID));}return true;}
 public function can_manage_library($r=null){if(!current_user_can('manage_nirmaan_library')||!current_user_can('use_nirmaan_modules'))return false;if($r&&isset($r['id'])){$p=get_post(absint($r['id']));return $p&&'nirmaan_library'===$p->post_type&&(current_user_can('use_nirmaan_advanced_modules')||!$this->post_requires_advanced_modules($p->ID));}return true;}
 public function get_content($r){$id=absint($r['id']);return rest_ensure_response(array('id'=>$id,'document'=>get_post_meta($id,'_nirmaan_builder_document',true)?:array('nodes'=>array())));}
 public function save_content($r){$id=absint($r['id']);$doc=$this->sanitize_document($r->get_json_params());$old=get_post_meta($id,'_nirmaan_builder_document',true);if(is_array($old)&&$old!==$doc)$this->record_revision('content',$id,$old,'');update_post_meta($id,'_nirmaan_builder_document',$doc);update_post_meta($id,'_nirmaan_builder_enabled',true);return rest_ensure_response(array('saved'=>true,'id'=>$id,'document'=>$doc,'builder_enabled'=>true));}
 public function list_templates(){$items=get_posts(array('post_type'=>'nirmaan_template','post_status'=>array('publish','draft'),'numberposts'=>100,'orderby'=>'meta_value_num','meta_key'=>'_nirmaan_priority','order'=>'DESC'));$out=array();foreach($items as $p)$out[]=array('id'=>$p->ID,'title'=>$p->post_title,'status'=>$p->post_status,'priority'=>(int)get_post_meta($p->ID,'_nirmaan_priority',true),'conditions'=>get_post_meta($p->ID,'_nirmaan_conditions',true)?:array(),'parts'=>get_post_meta($p->ID,'_nirmaan_template_parts',true)?:array());return rest_ensure_response($out);}
 public function create_template($r){$p=$r->get_json_params();$title=sanitize_text_field($p['title']??__('New Template','nirmaan-builder'));$id=wp_insert_post(array('post_type'=>'nirmaan_template','post_status'=>'publish','post_title'=>$title),true);if(is_wp_error($id))return $id;update_post_meta($id,'_nirmaan_priority',absint($p['priority']??10));update_post_meta($id,'_nirmaan_conditions',array('include'=>array(array('type'=>'entire_site')),'exclude'=>array()));update_post_meta($id,'_nirmaan_template_parts',array('header'=>array('nodes'=>array()),'body'=>array('nodes'=>array()),'footer'=>array('nodes'=>array())));update_post_meta($id,'_nirmaan_part_settings',array('header'=>array('active'=>true,'condition'=>''),'body'=>array('active'=>true,'condition'=>''),'footer'=>array('active'=>true,'condition'=>'')));return rest_ensure_response(array('id'=>$id,'title'=>$title));}
 public function get_template($r){$id=absint($r['id']);return rest_ensure_response(array('id'=>$id,'title'=>get_the_title($id),'status'=>get_post_status($id),'priority'=>(int)get_post_meta($id,'_nirmaan_priority',true),'conditions'=>get_post_meta($id,'_nirmaan_conditions',true)?:array(),'parts'=>get_post_meta($id,'_nirmaan_template_parts',true)?:array()));}
 public function save_template($r){$id=absint($r['id']);$p=$r->get_json_params();$post=get_post($id);if(!$post||'nirmaan_template'!==$post->post_type)return new \WP_Error('template_not_found',__('Template not found.','nirmaan-builder'),array('status'=>404));if(isset($p['title'])){$title=sanitize_text_field($p['title']);if(''===$title)return new \WP_Error('invalid_template_title',__('Template name cannot be empty.','nirmaan-builder'),array('status'=>400));wp_update_post(array('ID'=>$id,'post_title'=>$title));}if(isset($p['status'])){$status=sanitize_key($p['status']);if(!in_array($status,array('publish','draft'),true))return new \WP_Error('invalid_template_status',__('Template status must be Published or Draft.','nirmaan-builder'),array('status'=>400));wp_update_post(array('ID'=>$id,'post_status'=>$status));}if(isset($p['priority']))update_post_meta($id,'_nirmaan_priority',absint($p['priority']));if(isset($p['conditions'])&&is_array($p['conditions']))update_post_meta($id,'_nirmaan_conditions',$this->sanitize_conditions($p['conditions']));if(isset($p['part_settings'])&&is_array($p['part_settings'])){$current=get_post_meta($id,'_nirmaan_part_settings',true);$current=is_array($current)?$current:array();foreach(array('header','body','footer') as $section){if(!isset($p['part_settings'][$section])||!is_array($p['part_settings'][$section]))continue;$input=$p['part_settings'][$section];$condition=sanitize_key($input['condition']??'');$allowed=array('','front_page','all_pages','all_posts','archive','search','404','product','product_archive','shop','cart','checkout');$current[$section]=array('active'=>!empty($input['active']),'condition'=>in_array($condition,$allowed,true)?$condition:'');}update_post_meta($id,'_nirmaan_part_settings',$current);}if(isset($p['part'])&&in_array($p['part'],array('header','body','footer'),true)&&isset($p['document'])){$parts=get_post_meta($id,'_nirmaan_template_parts',true);$parts=is_array($parts)?$parts:array();$new_doc=$this->sanitize_document($p['document']);if(isset($parts[$p['part']])&&$parts[$p['part']]!==$new_doc)$this->record_revision('template',$id,$parts[$p['part']],$p['part']);$parts[$p['part']]=$new_doc;update_post_meta($id,'_nirmaan_template_parts',$parts);}return rest_ensure_response(array('saved'=>true,'id'=>$id));}
 public function duplicate_template($r){$id=absint($r['id']);$source=get_post($id);if(!$source||'nirmaan_template'!==$source->post_type)return new \WP_Error('template_not_found',__('Template not found.','nirmaan-builder'),array('status'=>404));$new_id=wp_insert_post(array('post_type'=>'nirmaan_template','post_status'=>'draft','post_title'=>sprintf(__('%s (Copy)','nirmaan-builder'),$source->post_title)),true);if(is_wp_error($new_id))return $new_id;foreach(array('_nirmaan_priority','_nirmaan_conditions','_nirmaan_template_parts','_nirmaan_part_settings') as $key){$value=get_post_meta($id,$key,true);if(false!==$value&&''!==$value)update_post_meta($new_id,$key,$value);}return rest_ensure_response(array('duplicated'=>true,'id'=>$new_id,'title'=>get_the_title($new_id),'status'=>'draft'));}
 public function delete_template($r){$id=absint($r['id']);$post=get_post($id);if(!$post||'nirmaan_template'!==$post->post_type)return new \WP_Error('template_not_found',__('Template not found.','nirmaan-builder'),array('status'=>404));wp_delete_post($id,true);return rest_ensure_response(array('deleted'=>true));}
 public function list_library(){$items=get_posts(array('post_type'=>'nirmaan_library','post_status'=>'publish','numberposts'=>200));$out=array();foreach($items as $p)$out[]=array('id'=>$p->ID,'title'=>$p->post_title,'global'=>(bool)get_post_meta($p->ID,'_nirmaan_global',true),'category'=>get_post_meta($p->ID,'_nirmaan_category',true),'document'=>get_post_meta($p->ID,'_nirmaan_library_document',true)?:array('nodes'=>array()));return rest_ensure_response($out);}
 private function sanitize_library_category($category){$category=sanitize_key($category);$allowed=array('section','template','module-preset','layout');return in_array($category,$allowed,true)?$category:'layout';}
 public function create_library_item($r){$p=$r->get_json_params();$title=sanitize_text_field($p['title']??__('Saved Layout','nirmaan-builder'));if(''===$title||strlen($title)>120)return new \WP_Error('invalid_library_title',__('Library item name is required and must be 120 characters or fewer.','nirmaan-builder'),array('status'=>400));$document=$this->sanitize_document($p['document']??array());if(empty($document['nodes']))return new \WP_Error('empty_library_item',__('Add at least one element before saving a Library item.','nirmaan-builder'),array('status'=>400));$id=wp_insert_post(array('post_type'=>'nirmaan_library','post_status'=>'publish','post_title'=>$title),true);if(is_wp_error($id))return $id;update_post_meta($id,'_nirmaan_library_document',$document);update_post_meta($id,'_nirmaan_global',!empty($p['global'])?1:0);update_post_meta($id,'_nirmaan_category',$this->sanitize_library_category($p['category']??'layout'));return rest_ensure_response(array('id'=>$id,'title'=>$title,'category'=>$this->sanitize_library_category($p['category']??'layout'),'global'=>!empty($p['global'])));}
 public function get_library_item($r){$id=absint($r['id']);return rest_ensure_response(array('id'=>$id,'title'=>get_the_title($id),'global'=>(bool)get_post_meta($id,'_nirmaan_global',true),'document'=>get_post_meta($id,'_nirmaan_library_document',true)?:array('nodes'=>array())));}
